// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title CYS Token
 * @dev A fully-featured ERC20 token with the following characteristics:
 * - Owner access control (for blacklist and pause/unpause)
 * - Role-based access control for minting and burning (BRIDGE_ROLE is permanently locked after deployment)
 * - Burnable functionality
 * - Pausable functionality
 * - Blacklist functionality
 */
contract CYS is ERC20, ERC20Burnable, ERC20Pausable, Ownable, AccessControl {
    using SafeERC20 for IERC20;

    // Role identifier for minter and burner
    bytes32 public constant BRIDGE_ROLE = keccak256("BRIDGE_ROLE");

    // Maximum batch size
    uint256 public constant MAX_BATCH = 100;

    // Blacklist mapping
    mapping(address => bool) private _blacklisted;

    // Events
    event Blacklisted(address indexed account, bool isBlacklisted);
    event Minted(address indexed to, uint256 amount);
    event BurnedFrom(address indexed from, uint256 amount);

    constructor(address bridge) ERC20("Cysic Token", "CYS") Ownable(msg.sender) {
        // Grant the bridge role to the bridge address
        // NOTE: BRIDGE_ROLE is permanently locked after deployment.
        // No DEFAULT_ADMIN_ROLE is granted, so no one can manage BRIDGE_ROLE after deployment.
        if (bridge != address(0)) {
            _grantRole(BRIDGE_ROLE, bridge);
        }
    }

    /**
     * @dev Add address to blacklist
     * @param account Address to add to blacklist
     */
    function addToBlacklist(address account) external onlyOwner {
        require(account != address(0), "CYS: cannot blacklist zero address");
        _blacklisted[account] = true;
        emit Blacklisted(account, true);
    }

    /**
     * @dev Remove address from blacklist
     * @param account Address to remove from blacklist
     */
    function removeFromBlacklist(address account) external onlyOwner {
        _blacklisted[account] = false;
        emit Blacklisted(account, false);
    }

    /**
     * @dev Check if address is blacklisted
     * @param account Address to check
     * @return Whether the address is blacklisted
     */
    function isBlacklisted(address account) external view returns (bool) {
        return _blacklisted[account];
    }

    /**
     * @dev Pause token transfers
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpause token transfers
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev Batch transfer function
     * @param recipients Array of recipient addresses
     * @param amounts Array of corresponding amounts
     */
    function batchTransfer(address[] calldata recipients, uint256[] calldata amounts) external whenNotPaused {
        require(recipients.length == amounts.length, "CYS: arrays length mismatch");
        require(recipients.length > 0, "CYS: empty arrays");
        require(recipients.length <= MAX_BATCH, "CYS: too long");

        for (uint256 i = 0; i < recipients.length; i++) {
            require(recipients[i] != address(0), "CYS: cannot transfer to zero address");
            require(amounts[i] > 0, "CYS: amount must be greater than zero");
            _transfer(msg.sender, recipients[i], amounts[i]);
        }
    }

    /**
     * @dev Mint tokens to a specified address
     * @param to Address to mint tokens to
     * @param amount Amount of tokens to mint
     */
    function mint(address to, uint256 amount) external onlyRole(BRIDGE_ROLE) whenNotPaused {
        require(to != address(0), "CYS: cannot mint to zero address");
        require(amount > 0, "CYS: amount must be greater than zero");
        _mint(to, amount);
        emit Minted(to, amount);
    }

    /**
     * @dev Burn tokens from a specified address
     * @param from Address to burn tokens from
     * @param amount Amount of tokens to burn
     */
    function burnFromAddress(address from, uint256 amount) external onlyRole(BRIDGE_ROLE) whenNotPaused {
        require(from != address(0), "CYS: cannot burn from zero address");
        require(amount > 0, "CYS: amount must be greater than zero");
        _burn(from, amount);
        emit BurnedFrom(from, amount);
    }

    /**
     * @dev Override _update function to add blacklist checks
     */
    function _update(address from, address to, uint256 value) internal override(ERC20, ERC20Pausable) {
        // Check if sender is blacklisted
        if (from != address(0)) {
            require(!_blacklisted[from], "CYS: sender is blacklisted");
        }
        // Check if recipient is blacklisted
        if (to != address(0)) {
            require(!_blacklisted[to], "CYS: recipient is blacklisted");
        }

        super._update(from, to, value);
    }
}

